--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/EntryEdgeIndicator.java
@@ -0,0 +1,230 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import java.util.Objects;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.Indicator;
+import org.ta4j.core.Trade.TradeType;
+import org.ta4j.core.indicators.helpers.ClosePriceIndicator;
+import org.ta4j.core.num.NaN;
+import org.ta4j.core.num.Num;
+
+/**
+ * Rolling realized edge score for entry signals.
+ *
+ * <p>
+ * The indicator measures how much better a signal performs than an
+ * unconditional baseline using only fully matured forward-return observations.
+ * At index {@code i}, the score is computed from signal bars whose
+ * {@code i + horizonBars} outcome is already known, which avoids look-ahead
+ * leakage.
+ * </p>
+ *
+ * <p>
+ * Values are returned in basis points. Positive values indicate the signal's
+ * recent realized outcomes beat the unconditional baseline; negative values
+ * indicate underperformance.
+ * </p>
+ *
+ * @since 0.22.7
+ */
+public class EntryEdgeIndicator extends CachedIndicator<Num> {
+
+    private static final double BASIS_POINTS = 10_000.0d;
+    private static final int NO_SIGNAL_INDEX = -1;
+
+    private final Indicator<Boolean> signalIndicator;
+    private final Indicator<Num> priceIndicator;
+    private final TradeType tradeType;
+    private final int horizonBars;
+    private final int lookbackSignals;
+    private final Indicator<Integer> latestMaturedSignalIndexIndicator;
+
+    /**
+     * Creates a long-side edge indicator using close price as the return source.
+     *
+     * @param signalIndicator indicator returning {@code true} on signal bars
+     * @param series          the bar series
+     * @param horizonBars     the forward-return horizon
+     * @param lookbackSignals the number of matured signal observations to include
+     * @since 0.22.7
+     */
+    public EntryEdgeIndicator(Indicator<Boolean> signalIndicator, BarSeries series, int horizonBars,
+            int lookbackSignals) {
+        this(signalIndicator, new ClosePriceIndicator(series), TradeType.BUY, horizonBars, lookbackSignals);
+    }
+
+    /**
+     * Creates a directional edge indicator using the supplied price source.
+     *
+     * @param signalIndicator indicator returning {@code true} on signal bars
+     * @param priceIndicator  price indicator used to measure forward returns
+     * @param tradeType       signal direction
+     * @param horizonBars     the forward-return horizon
+     * @param lookbackSignals the number of matured signal observations to include
+     * @since 0.22.7
+     */
+    public EntryEdgeIndicator(Indicator<Boolean> signalIndicator, Indicator<Num> priceIndicator, TradeType tradeType,
+            int horizonBars, int lookbackSignals) {
+        super(IndicatorUtils.requireSameSeries(signalIndicator, priceIndicator));
+        if (horizonBars < 1) {
+            throw new IllegalArgumentException("horizonBars must be greater than zero");
+        }
+        if (lookbackSignals < 1) {
+            throw new IllegalArgumentException("lookbackSignals must be greater than zero");
+        }
+        this.signalIndicator = Objects.requireNonNull(signalIndicator, "signalIndicator");
+        this.priceIndicator = Objects.requireNonNull(priceIndicator, "priceIndicator");
+        this.tradeType = Objects.requireNonNull(tradeType, "tradeType");
+        this.horizonBars = horizonBars;
+        this.lookbackSignals = lookbackSignals;
+        this.latestMaturedSignalIndexIndicator = createLatestMaturedSignalIndexIndicator();
+    }
+
+    /**
+     * {@inheritDoc}
+     *
+     * @since 0.22.7
+     */
+    @Override
+    protected Num calculate(int index) {
+        if (index < getCountOfUnstableBars()) {
+            return NaN.NaN;
+        }
+        int lastEligibleIndex = index - horizonBars;
+        int beginIndex = firstEligibleSignalIndex();
+        if (lastEligibleIndex < beginIndex) {
+            return NaN.NaN;
+        }
+        double signalTotal = 0.0d;
+        int signalCount = 0;
+        int signalIndex = latestMaturedSignalIndexIndicator.getValue(lastEligibleIndex);
+        while (signalIndex >= beginIndex && signalCount < lookbackSignals) {
+            double forwardReturn = signedForwardReturn(signalIndex);
+            if (!Double.isFinite(forwardReturn)) {
+                return NaN.NaN;
+            }
+            signalTotal += forwardReturn;
+            signalCount++;
+            int previousIndex = signalIndex - 1;
+            signalIndex = previousIndex >= beginIndex ? latestMaturedSignalIndexIndicator.getValue(previousIndex)
+                    : NO_SIGNAL_INDEX;
+        }
+        if (signalCount == 0) {
+            return NaN.NaN;
+        }
+
+        double baselineTotal = 0.0d;
+        int baselineCount = 0;
+        int baselineStart = Math.max(beginIndex, lastEligibleIndex - Math.max(signalCount, lookbackSignals) + 1);
+        for (int cursor = baselineStart; cursor <= lastEligibleIndex; cursor++) {
+            double forwardReturn = signedForwardReturn(cursor);
+            if (!Double.isFinite(forwardReturn)) {
+                continue;
+            }
+            baselineTotal += forwardReturn;
+            baselineCount++;
+        }
+        if (baselineCount == 0) {
+            return NaN.NaN;
+        }
+
+        double edgeBps = (signalTotal / signalCount) - (baselineTotal / baselineCount);
+        return getBarSeries().numFactory().numOf(edgeBps);
+    }
+
+    /**
+     * {@inheritDoc}
+     *
+     * @since 0.22.7
+     */
+    @Override
+    public int getCountOfUnstableBars() {
+        return Math.max(signalIndicator.getCountOfUnstableBars(), priceIndicator.getCountOfUnstableBars())
+                + horizonBars;
+    }
+
+    /**
+     * @return the signal indicator used to pick entry bars
+     * @since 0.22.7
+     */
+    public Indicator<Boolean> getSignalIndicator() {
+        return signalIndicator;
+    }
+
+    /**
+     * @return the price indicator used to measure forward returns
+     * @since 0.22.7
+     */
+    public Indicator<Num> getPriceIndicator() {
+        return priceIndicator;
+    }
+
+    /**
+     * @return the trade direction used to sign forward returns
+     * @since 0.22.7
+     */
+    public TradeType getTradeType() {
+        return tradeType;
+    }
+
+    /**
+     * @return the forward-return horizon
+     * @since 0.22.7
+     */
+    public int getHorizonBars() {
+        return horizonBars;
+    }
+
+    /**
+     * @return the number of matured signal observations included in the score
+     * @since 0.22.7
+     */
+    public int getLookbackSignals() {
+        return lookbackSignals;
+    }
+
+    private double signedForwardReturn(int entryIndex) {
+        int exitIndex = entryIndex + horizonBars;
+        Num entryPrice = priceIndicator.getValue(entryIndex);
+        Num exitPrice = priceIndicator.getValue(exitIndex);
+        if (Num.isNaNOrNull(entryPrice) || Num.isNaNOrNull(exitPrice) || entryPrice.isZero()) {
+            return Double.NaN;
+        }
+        Num basisPoints = entryPrice.getNumFactory().numOf(BASIS_POINTS);
+        double rawReturn = exitPrice.minus(entryPrice).dividedBy(entryPrice).multipliedBy(basisPoints).doubleValue();
+        return tradeType == TradeType.SELL ? -rawReturn : rawReturn;
+    }
+
+    private Indicator<Integer> createLatestMaturedSignalIndexIndicator() {
+        return new RecursiveCachedIndicator<>(getBarSeries()) {
+            @Override
+            protected Integer calculate(int index) {
+                int beginIndex = firstEligibleSignalIndex();
+                if (index < beginIndex) {
+                    return NO_SIGNAL_INDEX;
+                }
+                if (Boolean.TRUE.equals(signalIndicator.getValue(index))
+                        && Double.isFinite(signedForwardReturn(index))) {
+                    return index;
+                }
+                int previousIndex = index - 1;
+                return previousIndex >= beginIndex ? getValue(previousIndex) : NO_SIGNAL_INDEX;
+            }
+
+            @Override
+            public int getCountOfUnstableBars() {
+                return EntryEdgeIndicator.this.getCountOfUnstableBars();
+            }
+        };
+    }
+
+    private int firstEligibleSignalIndex() {
+        return Math.max(getBarSeries().getBeginIndex(),
+                getBarSeries().getBeginIndex() + signalIndicator.getCountOfUnstableBars());
+    }
+
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/StretchZScoreIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/StretchZScoreIndicator.java
new file mode 100644
index 000000000..17ecbbec0
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/StretchZScoreIndicator.java
@@ -0,0 +1,161 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import java.util.Objects;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.Indicator;
+import org.ta4j.core.indicators.averages.SMAIndicator;
+import org.ta4j.core.indicators.helpers.ClosePriceIndicator;
+import org.ta4j.core.indicators.numeric.NumericIndicator;
+import org.ta4j.core.indicators.statistics.StandardDeviationIndicator;
+import org.ta4j.core.indicators.statistics.ZScoreIndicator;
+import org.ta4j.core.num.Num;
+
+/**
+ * Rolling z-score that measures how stretched an indicator is versus a
+ * reference signal.
+ *
+ * <p>
+ * The indicator computes the deviation between a source and reference
+ * indicator, then normalizes that deviation by the rolling standard deviation
+ * of the deviation series. Positive values indicate the source is extended
+ * above the reference, negative values indicate it is extended below the
+ * reference, and values near zero indicate little stretch.
+ * </p>
+ *
+ * <p>
+ * The default convenience constructors use close price and a simple moving
+ * average, but callers may supply any source/reference pair such as VWAP,
+ * anchored VWAP, or a band midpoint.
+ * </p>
+ *
+ * @since 0.22.7
+ */
+public class StretchZScoreIndicator extends CachedIndicator<Num> {
+
+    private final Indicator<Num> sourceIndicator;
+    private final Indicator<Num> referenceIndicator;
+    private final Indicator<Num> deviationIndicator;
+    private final StandardDeviationIndicator standardDeviationIndicator;
+    private final ZScoreIndicator zScoreIndicator;
+    private final int barCount;
+
+    /**
+     * Creates a close-price stretch indicator against a rolling SMA reference.
+     *
+     * @param series   the bar series
+     * @param barCount the rolling window used for the stretch calculation
+     * @since 0.22.7
+     */
+    public StretchZScoreIndicator(BarSeries series, int barCount) {
+        this(new ClosePriceIndicator(series), barCount);
+    }
+
+    /**
+     * Creates a stretch indicator against a rolling SMA reference built from the
+     * supplied source indicator.
+     *
+     * @param sourceIndicator the source indicator to normalize
+     * @param barCount        the rolling window used for the stretch calculation
+     * @since 0.22.7
+     */
+    public StretchZScoreIndicator(Indicator<Num> sourceIndicator, int barCount) {
+        this(sourceIndicator, new SMAIndicator(Objects.requireNonNull(sourceIndicator, "sourceIndicator"), barCount),
+                barCount);
+    }
+
+    /**
+     * Creates a stretch indicator for a custom source/reference pair.
+     *
+     * @param sourceIndicator    the indicator whose stretch should be measured
+     * @param referenceIndicator the indicator acting as the reference level
+     * @param barCount           the rolling window used for the stretch calculation
+     * @since 0.22.7
+     */
+    public StretchZScoreIndicator(Indicator<Num> sourceIndicator, Indicator<Num> referenceIndicator, int barCount) {
+        super(IndicatorUtils.requireSameSeries(sourceIndicator, referenceIndicator));
+        if (barCount < 1) {
+            throw new IllegalArgumentException("barCount must be greater than zero");
+        }
+        this.sourceIndicator = Objects.requireNonNull(sourceIndicator, "sourceIndicator");
+        this.referenceIndicator = Objects.requireNonNull(referenceIndicator, "referenceIndicator");
+        this.barCount = barCount;
+        this.deviationIndicator = NumericIndicator.of(sourceIndicator).minus(referenceIndicator);
+        this.standardDeviationIndicator = new StandardDeviationIndicator(deviationIndicator, barCount);
+        this.zScoreIndicator = new ZScoreIndicator(deviationIndicator, standardDeviationIndicator);
+    }
+
+    /**
+     * {@inheritDoc}
+     *
+     * @since 0.22.7
+     */
+    @Override
+    protected Num calculate(int index) {
+        return zScoreIndicator.getValue(index);
+    }
+
+    /**
+     * {@inheritDoc}
+     *
+     * @since 0.22.7
+     */
+    @Override
+    public int getCountOfUnstableBars() {
+        return zScoreIndicator.getCountOfUnstableBars();
+    }
+
+    /**
+     * @return the source indicator being normalized
+     * @since 0.22.7
+     */
+    public Indicator<Num> getSourceIndicator() {
+        return sourceIndicator;
+    }
+
+    /**
+     * @return the reference indicator used as the stretch anchor
+     * @since 0.22.7
+     */
+    public Indicator<Num> getReferenceIndicator() {
+        return referenceIndicator;
+    }
+
+    /**
+     * @return the deviation indicator ({@code source - reference})
+     * @since 0.22.7
+     */
+    public Indicator<Num> getDeviationIndicator() {
+        return deviationIndicator;
+    }
+
+    /**
+     * @return the rolling standard deviation of the deviation series
+     * @since 0.22.7
+     */
+    public StandardDeviationIndicator getStandardDeviationIndicator() {
+        return standardDeviationIndicator;
+    }
+
+    /**
+     * @return the rolling bar count used for the stretch calculation
+     * @since 0.22.7
+     */
+    public int getBarCount() {
+        return barCount;
+    }
+
+    /**
+     * {@inheritDoc}
+     *
+     * @since 0.22.7
+     */
+    @Override
+    public String toString() {
+        return getClass().getSimpleName() + " barCount: " + barCount;
+    }
+
+}
